class Solution {
    public int longestConsecutive(int[] nums) {
        Set<Integer> s = new HashSet<>();
        for (int x : nums) s.add(x);
        int best = 0;
        for (int x : s) {                           // 遍历集合，不是遍历 nums
            if (s.contains(x - 1)) {
                continue;                           // 不是起点，跳过
            }
            int y = x;
            while (s.contains(y + 1)) {
                y++;
            }
            best = Math.max(best, y - x + 1);
        }
        return best;
    }
}

